def dashboard_health_payload() -> dict[str, Any]:
    from version_roles import build_version_role_contract
    version_roles = build_version_role_contract()
    return {
        "ok": True,
        "service": "eidolon-dashboard",
        "version": RUNTIME_VERSION,
        "working_source_version": version_roles.get("working_source_version"),
        "installed_version": version_roles.get("installed_version"),
        "candidate_version": version_roles.get("candidate_version"),
        "version_roles": version_roles,
        "installed": False,
        "certified": False,
        "startup_target_seconds": STARTUP_TARGET_SECONDS,
        "dashboard_module_uptime_seconds": max(0.0, time.perf_counter() - _DASHBOARD_IMPORTED_MONOTONIC),
        "provider_contacted": False,
        "runtime_mutation_performed": False,
        "lazy_modules": lazy_import_status(list(_DASHBOARD_LAZY_MODULES)),
        "general_cli_sentinels_loaded": {name: name in sys.modules for name in _DASHBOARD_GENERAL_CLI_SENTINELS},
        "conversation_startup": conversation_startup_status(),
        "api_prewarm": __import__("dashboard_performance").prewarm_status(),
        "deferred_services": {
            key: value
            for key, value in deferred_dashboard_status().items()
            if key != "modules"
        },
    }


def dispatch_api(*args: Any, **kwargs: Any):
    method = str(args[0] if args else kwargs.get("method") or "").upper()
    path = str(args[1] if len(args) > 1 else kwargs.get("path") or "")
    if method == "GET" and path == "/api/runtime-status":
        from dashboard_fast_status import build_fast_runtime_status
        return 200, build_fast_runtime_status()
    from api_server import dispatch_api as _dispatch_api
    return _dispatch_api(*args, **kwargs)


def parse_request_body(*args: Any, **kwargs: Any):
    return parse_dashboard_request_body(*args, **kwargs)


def _to_jsonable(value: Any) -> Any:
    return dashboard_jsonable(value)

def _operational_readiness_function(name: str):
    import operational_readiness as _operational_readiness
    return getattr(_operational_readiness, name)

