def render_settings() -> str:
    settings = load_settings()
    rows = "".join(f"<tr><td>{_safe(k)}</td><td>{_safe(v)}</td></tr>" for k, v in sorted(settings.items()))
    form = """
<form method='post' action='/action' class='stack'>
<input type='hidden' name='action' value='set_setting'>
<label>Setting key <input name='key' placeholder='local_model'></label>
<label>Value <input name='value' placeholder='qwen2.5:7b'></label>
<button type='submit'>Update setting</button>
</form>
"""
    health = settings_health()
    from model_training.training_operator import build_training_evidence_status
    training = build_training_evidence_status()
    policy = dict(training.get("policy") or {})
    counts = dict(training.get("counts") or {})
    readiness = dict(training.get("readiness") or {})
    checked = lambda key: " checked" if policy.get(key) is True else ""
    capture_form = f"""
<form method='post' action='/action' class='stack'>
<input type='hidden' name='action' value='set_training_capture_policy'>
<label><input type='checkbox' name='coding_repair_enabled' value='true'{checked('coding_repair_enabled')}> Coding / repair</label>
<label><input type='checkbox' name='research_enabled' value='true'{checked('research_enabled')}> Research</label>
<label><input type='checkbox' name='planning_enabled' value='true'{checked('planning_enabled')}> Planning</label>
<label><input type='checkbox' name='tool_governance_enabled' value='true'{checked('tool_governance_enabled')}> Tool / governance</label>
<label><input type='checkbox' name='conversation_enabled' value='true'{checked('conversation_enabled')}> Conversation</label>
<label><input type='checkbox' name='auto_sanitize_enabled' value='true'{checked('auto_sanitize_enabled')}> Auto-sanitize</label>
<button type='submit'>Save capture settings</button>
</form>
"""
    training_table = "".join(
        f"<tr><td>{_safe(label)}</td><td>{_safe(value)}</td></tr>" for label, value in [
            ("Raw records", counts.get("raw", 0)), ("Sanitized records", counts.get("sanitized", 0)),
            ("Approved records", counts.get("approved", 0)), ("Capture failures", counts.get("capture_failures", 0)),
            ("Preference pairs", counts.get("preference_pairs", 0)), ("Frozen eval cases", readiness.get("frozen_eval_cases", 0)),
            ("Latest dataset", training.get("latest_dataset_version") or "[none]"),
            ("Provenance", training.get("provenance_status")), ("Baseline benchmark", training.get("baseline_benchmark_status")),
        ]
    )
    boundaries = "<table><tr><th>Boundary</th><th>State</th></tr>" + "".join(
        f"<tr><td>{_safe(label)}</td><td><b>{_safe(value)}</b></td></tr>" for label, value in [
            ("Auto-approve", "DISABLED"), ("Automatic dataset export", "DISABLED"),
            ("Training authorized", "NO"), ("Model promotion authorized", "NO"),
        ]
    ) + "</table>"
    progress = (
        f"<p>Approved examples: <b>{_safe(readiness.get('approved_examples', 0))}</b> / {_safe(readiness.get('approved_target', 5000))}</p>"
        f"<p>Frozen evaluation cases: <b>{_safe(readiness.get('frozen_eval_cases', 0))}</b> / {_safe(readiness.get('frozen_eval_target', 500))}</p>"
        f"<p>Readiness gate: <b>{'READY' if readiness.get('ready') else 'NOT READY'}</b></p>"
    )
    return _layout(
        "/settings",
        _card("Training Evidence Capture", capture_form)
        + _card("Training Evidence Status", f"<table><tr><th>Metric</th><th>Value</th></tr>{training_table}</table>{progress}")
        + _card("Training Authority Boundaries", boundaries)
        + _card("Settings", f"<table><tr><th>Key</th><th>Value</th></tr>{rows}</table>")
        + _card("Update Setting", form)
        + _card("Settings Health", _json_block(health)),
    )

def _report_status_card(title: str, report: dict[str, Any], extra: str = "") -> str:
    status = str(report.get("status", "unknown")).upper()
    status_class = "good" if status in {"PASS", "READY", "PREVIEW_COMPLETE", "LIVE_COMPLETE"} else "warn" if status in {"WARN", "READY_WITH_WARNINGS", "LIMITED_MODE"} else "badtext"
    score = f"<p class='muted'>Score: {_safe(report.get('score'))}%</p>" if "score" in report else ""
    return _card(title, f"<div class='kpi {status_class}'>{_safe(status)}</div><p>{_safe(report.get('message', ''))}</p>{score}{extra}")

def render_stabilization() -> str:
    report = build_stabilization_dashboard_summary(project_id="eidolon")
    counts = report.get("counts") or {}
    blockers = report.get("blockers") or []
    warnings = report.get("warnings") or []
    blocker_html = _small_list([
        _safe(f"[{item.get('category', 'general')}] {item.get('name')}: {item.get('message')}")
        for item in blockers[:12]
    ]) if blockers else "<p class='muted'>No blockers found in the bounded summary.</p>"
    warning_html = _small_list([
        _safe(f"[{item.get('category', 'general')}] {item.get('name')}: {item.get('message')}")
        for item in warnings[:12]
    ]) if warnings else "<p class='muted'>No warnings found in the bounded summary.</p>"
    deferred = _small_list([_safe(item) for item in report.get("deferred_full_checks") or []])
    command_text = "\n".join(report.get("recommended_commands") or [])
    body = f"""
<p>This page uses a bounded, read-only stabilization summary so ordinary dashboard GET requests do not recompile the project, import every subsystem, or probe optional dependencies. Full diagnostics remain explicit.</p>
<div class='grid'>
  {_report_status_card('Bounded Checkpoint Summary', report)}
  <section class='card'><h2>Pass</h2><div class='kpi good'>{_safe(counts.get('pass', 0))}</div></section>
  <section class='card'><h2>Warn</h2><div class='kpi warn'>{_safe(counts.get('warn', 0))}</div></section>
  <section class='card'><h2>Fail</h2><div class='kpi badtext'>{_safe(counts.get('fail', 0))}</div></section>
</div>
<div class='grid'>
  {_card('Blockers', blocker_html)}
  {_card('Warnings', warning_html)}
  {_card('Deferred Full Checks', deferred)}
</div>
<h3>Full verification</h3>
<p><a href='/api/stabilization-checkpoint?full=true'>Open full JSON checkpoint report</a> | <a href='/doctor'>Open Doctor page</a></p>
<pre>{_safe(command_text)}</pre>
"""
    summary_text = stabilization_checkpoint_text(report, full=False)
    return _layout("/stabilization", _card("Stabilization Checkpoint", body) + _card("Bounded summary", _text_block(summary_text)))

