def _doctor_lazy_section_html() -> str:
    items = []
    for section in DOCTOR_LAZY_DIAGNOSTIC_SECTIONS:
        items.append(
            "<li><strong>{name}</strong>: <a href='{route}'>open diagnostic surface</a><br><span class='muted'>{reason}</span></li>".format(
                name=_safe(section["name"]),
                route=_safe(section["route"]),
                reason=_safe(section["reason"]),
            )
        )
    return "<ul>" + "".join(items) + "</ul>"

def render_doctor() -> str:
    from dashboard_doctor_headroom_repair import (
        build_doctor_dashboard_headroom_snapshot,
        doctor_dashboard_headroom_snapshot_text,
    )

    snapshot = build_doctor_dashboard_headroom_snapshot(project_id="eidolon", root=Path(__file__).resolve().parents[1])
    rows = snapshot.get("diagnostic_rows") or []
    row_html = "".join(
        "<tr><td>{label}</td><td><code>{route}</code></td><td>{lane}</td><td>{cache}</td><td>{ok}</td></tr>".format(
            label=_safe(row.get("label")),
            route=_safe(row.get("route")),
            lane=_safe(row.get("lane")),
            cache=_safe(row.get("cache_only")),
            ok=_safe(row.get("ok")),
        )
        for row in rows
    )
    body = f"""
<p>Doctor mode now renders a true bounded headroom shell backed by the preview-only diagnostic cache instead of rebuilding and dumping heavyweight operational reports on every dashboard click. Astonishingly, not doing extra work is faster.</p>
<div class='grid'>
  <section class='card' data-tip='v1052 keeps /doctor bounded by reading preview-cache metadata instead of running the full operational readiness fan-out.'><h3>Doctor Headroom</h3><div class='kpi good'>{_safe(snapshot.get('status', 'unknown')).upper()}</div><p>Render mode: {_safe(snapshot.get('render_mode'))}</p></section>
  <section class='card' data-tip='The diagnostic preview cache is static/advisory and does not call live diagnostics during dashboard rendering.'><h3>Preview Cache</h3><p>Rows: {_safe(snapshot.get('diagnostic_row_count'))}. Cache elapsed: {_safe(snapshot.get('cache_elapsed_ms'))} ms / {_safe(snapshot.get('headroom_budget_ms'))} ms.</p><p>Storm avoided: {_safe(snapshot.get('diagnostic_storm_avoided'))}</p></section>
  <section class='card' data-tip='Deep doctor, patch integrity, task review, recovery, hardening, and project snapshot reports remain available through deliberate API links.'><h3>Deep Diagnostics</h3><p>Primary operational reports are deferred. Manual dashboard routing remains authoritative.</p></section>
</div>
<p><a href='/api/doctor?full=true'>Doctor JSON</a> | <a href='/api/doctor/diagnostic-preview-cache'>Diagnostic preview cache</a> | <a href='/api/controlled-self-build/lightweight-preview'>Controlled self-build lightweight preview</a> | <a href='/api/project-snapshot'>Snapshot JSON</a></p>
"""
    diagnostic_table = "<table><tr><th>Label</th><th>Route</th><th>Lane</th><th>Cache only</th><th>OK</th></tr>" + row_html + "</table>"
    lazy = _card("Deferred diagnostics", _doctor_lazy_section_html())
    summary = _card("Primary operational reports", _text_block(doctor_dashboard_headroom_snapshot_text(snapshot, full=False)))
    return _layout("/doctor", _card("Doctor Mode", body) + _card("Preview diagnostic rows", diagnostic_table) + lazy + summary)

