class EidolonDashboardHandler(BaseHTTPRequestHandler):
    server_version = "EidolonDashboard/30.0"

    def _client_disconnected(self, error: BaseException) -> bool:
        return isinstance(error, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError))

    def _send_json(self, payload: dict[str, Any], status: int = 200) -> bool:
        encoded = json.dumps(_to_jsonable(payload), indent=2, default=str).encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(encoded)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(encoded)
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            # dashboard response write skipped because client disconnected; do not try to send a second error response.
            return False

    def _send_html(self, html: str, status: int = 200) -> bool:
        if str(html).lstrip().lower().startswith("<!doctype html>"):
            from dashboard_performance import optimize_dashboard_html_assets
            html = optimize_dashboard_html_assets(html)
        encoded = html.encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(encoded)))
            self.end_headers()
            self.wfile.write(encoded)
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            # dashboard response write skipped because client disconnected; do not try to send a second error response.
            return False

    def _send_sse_event(self, event: str, payload: dict[str, Any]) -> None:
        encoded = f"event: {event}\ndata: {json.dumps(_to_jsonable(payload), default=str)}\n\n".encode("utf-8")
        self.wfile.write(encoded)
        self.wfile.flush()

    def _redirect(self, location: str = "/") -> None:
        self.send_response(303)
        self.send_header("Location", location)
        self.end_headers()

    def _send_lightweight_json(self, payload: dict[str, Any], status: int = 200) -> bool:
        encoded = json.dumps(payload, indent=2, default=str).encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(encoded)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(encoded)
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return False

    def _send_static_asset(self, name: str) -> bool:
        from dashboard_performance import load_dashboard_asset
        asset = load_dashboard_asset(name)
        if asset is None:
            self._send_html("Not found", status=404)
            return False
        content_type, data = asset
        try:
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "public, max-age=3600")
            self.end_headers()
            self.wfile.write(data)
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return False

    def _same_origin_request(self) -> bool:
        """Accept browser mutations only from the dashboard's exact origin.

        Non-browser/local automation that omits Origin remains supported. Browsers
        supply Origin for cross-origin CORS requests and form/fetch mutations, so
        a foreign page cannot use the loopback dashboard as a confused deputy.
        """
        origin = str(self.headers.get("Origin") or "").strip()
        if not origin:
            return True
        try:
            parsed = urlparse(origin)
        except ValueError:
            return False
        host = str(self.headers.get("Host") or "").strip().lower()
        return bool(parsed.scheme in {"http", "https"} and parsed.netloc.lower() == host and not parsed.username and not parsed.password)

    def _reject_cross_origin_mutation(self) -> bool:
        if self._same_origin_request():
            return False
        self._send_json({
            "ok": False,
            "status": "cross_origin_request_blocked",
            "error": "State-changing dashboard requests must originate from the dashboard itself.",
            "content_free": True,
        }, status=403)
        return True

    def do_OPTIONS(self) -> None:
        if self._reject_cross_origin_mutation():
            return
        self._send_json({"ok": True, "methods": ["GET", "POST", "OPTIONS"]})

